import {STYLES} from './ascension.js?v=6';
const TAU=Math.PI*2;
export function drawAscension(g,wings,aura,t){if(aura?.rank&&aura.visible!==false){const r=aura.rank,c=STYLES[aura.style]?.color||'#e9cd8b',radius=17+r*1.2;g.save();const glow=g.createRadialGradient(0,0,2,0,0,radius*1.6);glow.addColorStop(0,c+'20');glow.addColorStop(1,c+'00');g.fillStyle=glow;g.fillRect(-radius*1.6,-radius*.6,radius*3.2,radius*1.2);g.strokeStyle=c;g.lineWidth=.7+r*.04;g.globalAlpha=.4+Math.sin(t*2)*.12;g.beginPath();g.ellipse(0,2,radius,radius*.38,0,0,TAU);g.stroke();if(r>=3){g.save();g.translate(0,2);g.scale(1,.38);g.rotate(t*.3);g.beginPath();g.arc(0,0,radius*.78,0,TAU);g.stroke();const n=r>=8?10:6;for(let j=0;j<n;j++){const q=j*TAU/n;g.beginPath();g.moveTo(Math.cos(q)*radius*.7,Math.sin(q)*radius*.7);g.lineTo(Math.cos(q)*radius,Math.sin(q)*radius);g.stroke();}g.restore();}g.globalAlpha=.65;const particles=2+r;for(let j=0;j<particles;j++){const q=t*.7+j*2.4,h=((t*11+j*7)%60),x=Math.cos(q)*radius;g.beginPath();g.arc(x,1-h,.5+r*.045,0,TAU);g.fillStyle=c;g.fill();}if(r>=5){g.globalAlpha=.12;g.beginPath();g.ellipse(0,-37,18+r,42+r,0,0,TAU);g.stroke();}if(r>=10){g.globalAlpha=.65;g.beginPath();g.ellipse(0,-98,15,5,0,0,TAU);g.stroke();for(let j=0;j<3;j++){g.beginPath();g.arc(Math.sin(t+j*2.1)*25,-46+Math.cos(t+j*2.1)*25,1.5,0,TAU);g.fillStyle='#fff6dd';g.fill();}}g.restore();}
if(wings?.rank&&wings.visible!==false){const r=wings.rank,c=STYLES[wings.style]?.color||'#e6c48d',size=25+r*2.4,form=r<3?0:r<5?1:r<8?2:r<10?3:4;g.save();g.translate(0,-54);for(const sign of [-1,1]){g.save();g.scale(sign,1);g.rotate(Math.sin(t*1.4)*(.035+r*.002));const grad=g.createLinearGradient(7,0,size,-29);grad.addColorStop(0,'#21394b');grad.addColorStop(.45,c+'aa');grad.addColorStop(1,c);g.fillStyle=grad;g.strokeStyle=c;g.lineWidth=.65;g.beginPath();g.moveTo(5,4);g.bezierCurveTo(size*.5,-25,size*.7,-39,size,-43-r*.7);g.bezierCurveTo(size*.92,-14,size*.6,7,8,21);g.closePath();g.fill();g.stroke();const feathers=form>=3?8:5;for(let n=0;n<feathers;n++){const q=n/(feathers-1),x=size*(.45+q*.55),y=-33+q*32,tipX=x+(form===1?10:form>=2?14:8),tipY=y-10-q*6;g.beginPath();g.moveTo(9,9+q*12);if(form===0)g.bezierCurveTo(x*.7,y+20,tipX,y+8,tipX,tipY);else g.lineTo(tipX,tipY);g.lineTo(x*.85,y+13);g.closePath();g.fillStyle=n%2?c+'a8':grad;g.fill();g.strokeStyle=n%2?'#eff5ed99':c;g.stroke();}if(form>=3){g.globalAlpha=.6;g.beginPath();g.moveTo(7,10);g.bezierCurveTo(size*.65,8,size*.85,19,size*.72,38);g.lineTo(size*.4,22);g.closePath();g.fillStyle=grad;g.fill();g.stroke();g.globalAlpha=1;}if(form>=4){g.strokeStyle='#fff2b8';g.lineWidth=1;g.beginPath();g.moveTo(8,2);g.bezierCurveTo(size*.7,-36,size,-42,size+10,-50);g.stroke();}for(let n=0;n<Math.ceil(r/2);n++){const q=t*1.2+n*1.8;g.fillStyle=c;g.globalAlpha=.5+.3*Math.sin(q);g.beginPath();g.arc(20+Math.cos(q)*size*.65,-16+Math.sin(q)*28,.65+r*.07,0,TAU);g.fill();}g.restore();}g.restore();}}
